package service

import (
	"fmt"
	"sync"

	"github.com/google/uuid"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

// UserService manages user-related operations
type UserService struct {
	users  map[string]User
	mutex  sync.RWMutex
	nextID int // Only used if not using UUIDs, kept for legacy compatibility for a bit.
}

// NewUserService creates and returns a new UserService
func NewUserService() *UserService {
	return &UserService{
		users:  make(map[string]User),
		nextID: 1,
	}
}

// GetAllUsers returns a list of all users
func (s *UserService) GetAllUsers() []User {
	s.mutex.RLock()
	defer s.mutex.RUnlock()
	var list []User
	for _, u := range s.users {
		list = append(list, u)
	}
	return list
}

// CreateUser creates a new user and adds it to the system
func (s *UserService) CreateUser(user User) (User, error) {
	s.mutex.Lock()
	defer s.mutex.Unlock()

	// Generate a new UUID for the user ID
	user.ID = uuid.New().String()
	s.users[user.ID] = user
	return user, nil
}

// GetUserByID returns a user by their ID
func (s *UserService) GetUserByID(id string) (User, bool) {
	s.mutex.RLock()
	defer s.mutex.RUnlock()
	user, ok := s.users[id]
	return user, ok
}

package api

import (
	"encoding/json"
	"net/http"

	"legacy_refactor/internal/service"
)

// Handlers struct holds the service dependency
type Handlers struct {
	UserService *service.UserService
}

// GetUsersHandler handles GET requests for /users
func (h *Handlers) GetUsersHandler(w http.ResponseWriter, r *http.Request) {
	users := h.UserService.GetAllUsers()
	json.NewEncoder(w).Encode(users)
}

// CreateUserHandler handles POST requests for /users
func (h *Handlers) CreateUserHandler(w http.ResponseWriter, r *http.Request) {
	var user service.User
	if err := json.NewDecoder(r.Body).Decode(&user); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	createdUser, err := h.UserService.CreateUser(user)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(createdUser)
}

// GetUserByIDHandler handles GET requests for /users/{id}
func (h *Handlers) GetUserByIDHandler(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Path[len("/users/"):]
	user, ok := h.UserService.GetUserByID(id)
	if !ok {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(user)
}

package main

import (
	"log"
	"net/http"

	"experiment/internal/api"
	"experiment/internal/service"
)

func main() {
	userService := service.NewUserService()
	handlers := &api.Handlers{
		UserService: userService,
	}

	http.HandleFunc("/users", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			handlers.GetUsersHandler(w, r)
		case http.MethodPost:
			handlers.CreateUserHandler(w, r)
		default:
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		}
	})

	http.HandleFunc("/users/", func(w http.ResponseWriter, r *http.Request) {
		if r.Method == http.MethodGet {
			handlers.GetUserByIDHandler(w, r)
		} else {
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		}
	})

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package service

import (
	"testing"
)

func TestNewUserService(t *testing.T) {
	svc := NewUserService()
	if svc == nil {
		t.Errorf("Expected NewUserService to return a non-nil service, got nil")
	}
	if svc.users == nil {
		t.Errorf("Expected users map to be initialized, got nil")
	}
	if svc.nextID != 1 {
		t.Errorf("Expected nextID to be 1, got %d", svc.nextID)
	}
}

func TestUserService_CreateUser(t *testing.T) {
	svc := NewUserService()
	user := User{Name: "Test User", Email: "test@example.com"}

	createdUser, err := svc.CreateUser(user)
	if err != nil {
		t.Fatalf("Expected no error, got %v", err)
	}

	if createdUser.ID == "" {
		t.Errorf("Expected user ID to be generated, got empty string")
	}
	if createdUser.Name != user.Name || createdUser.Email != user.Email {
		t.Errorf("Created user mismatch. Expected %+v, got %+v", user, createdUser)
	}

	// Check if the user is actually stored
	storedUser, ok := svc.GetUserByID(createdUser.ID)
	if !ok {
		t.Errorf("Expected user to be stored, but not found")
	}
	if storedUser.Name != user.Name {
		t.Errorf("Stored user name mismatch. Expected %s, got %s", user.Name, storedUser.Name)
	}
}

func TestUserService_GetAllUsers(t *testing.T) {
	svc := NewUserService()
	user1 := User{Name: "User 1", Email: "user1@example.com"}
	user2 := User{Name: "User 2", Email: "user2@example.com"}

	svc.CreateUser(user1)
	svc.CreateUser(user2)

	users := svc.GetAllUsers()
	if len(users) != 2 {
		t.Errorf("Expected 2 users, got %d", len(users))
	}
}

func TestUserService_GetUserByID(t *testing.T) {
	svc := NewUserService()
	user := User{Name: "Find Me", Email: "findme@example.com"}

	createdUser, _ := svc.CreateUser(user)

	foundUser, ok := svc.GetUserByID(createdUser.ID)
	if !ok {
		t.Errorf("Expected to find user with ID %s", createdUser.ID)
	}
	if foundUser.Name != user.Name {
		t.Errorf("Found user name mismatch. Expected %s, got %s", user.Name, foundUser.Name)
	}

	_, ok = svc.GetUserByID("non-existent-id")
	if ok {
		t.Errorf("Expected not to find user with non-existent ID")
	}
}

package api

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"

	"experiment/internal/service"
)

func TestGetUsersHandler(t *testing.T) {
	// Setup service and handlers
	svc := service.NewUserService()
	h := &Handlers{UserService: svc}

	// Create a few users
	svc.CreateUser(service.User{Name: "Alice", Email: "alice@example.com"})
	svc.CreateUser(service.User{Name: "Bob", Email: "bob@example.com"})

	// Create a request to pass to our handler.
	req, err := http.NewRequest("GET", "/users", nil)
	if err != nil {
		t.Fatal(err)
	}

	// We create a ResponseRecorder (which satisfies http.ResponseWriter) to record the response.
	rr := httptest.NewRecorder()
	handler := http.HandlerFunc(h.GetUsersHandler)

	// Our handlers satisfy http.Handler, so we can call their ServeHTTP method
	// directly and pass in our Request and ResponseRecorder.
	handler.ServeHTTP(rr, req)

	// Check the status code is what we expect.
	if status := rr.Code; status != http.StatusOK {
		t.Errorf("handler returned wrong status code: got %v want %v",
			status, http.StatusOK)
	}

	// Check the response body.
	var users []service.User
	if err := json.NewDecoder(rr.Body).Decode(&users); err != nil {
		t.Fatalf("Could not decode response: %v", err)
	}

	if len(users) != 2 {
		t.Errorf("handler returned unexpected number of users: got %v want %v",
			len(users), 2)
	}

	// Further checks on user data can be added if necessary
}

func TestCreateUserHandler(t *testing.T) {
	// Setup service and handlers
	svc := service.NewUserService()
	h := &Handlers{UserService: svc}

	// Create a user to send in the request body
	newUser := service.User{Name: "Charlie", Email: "charlie@example.com"}
	body, _ := json.Marshal(newUser)

	// Create a request to pass to our handler.
	req, err := http.NewRequest("POST", "/users", bytes.NewBuffer(body))
	if err != nil {
		t.Fatal(err)
	}
	req.Header.Set("Content-Type", "application/json")

	// We create a ResponseRecorder to record the response.
	rr := httptest.NewRecorder()
	handler := http.HandlerFunc(h.CreateUserHandler)

	// Our handlers satisfy http.Handler, so we can call their ServeHTTP method
	// directly and pass in our Request and ResponseRecorder.
	handler.ServeHTTP(rr, req)

	// Check the status code is what we expect.
	if status := rr.Code; status != http.StatusCreated {
		t.Errorf("handler returned wrong status code: got %v want %v",
			status, http.StatusCreated)
	}

	// Check the response body.
	var createdUser service.User
	if err := json.NewDecoder(rr.Body).Decode(&createdUser); err != nil {
		t.Fatalf("Could not decode response: %v", err)
	}

	if createdUser.ID == "" {
		t.Errorf("Expected user ID to be generated, got empty string")
	}
	if createdUser.Name != newUser.Name || createdUser.Email != newUser.Email {
		t.Errorf("Created user mismatch. Expected %+v, got %+v", newUser, createdUser)
	}

	// Verify user is in the service
	_, ok := svc.GetUserByID(createdUser.ID)
	if !ok {
		t.Errorf("Expected user to be stored in service, but not found")
	}
}

func TestGetUserByIDHandler(t *testing.T) {
	// Setup service and handlers
	svc := service.NewUserService()
	h := &Handlers{UserService: svc}

	// Create a user to fetch
	userToFetch := service.User{Name: "David", Email: "david@example.com"}
	createdUser, _ := svc.CreateUser(userToFetch)

	// Test case 1: User found
	req, err := http.NewRequest("GET", "/users/"+createdUser.ID, nil)
	if err != nil {
		t.Fatal(err)
	}

	rr := httptest.NewRecorder()
	handler := http.HandlerFunc(h.GetUserByIDHandler)
	handler.ServeHTTP(rr, req)

	if status := rr.Code; status != http.StatusOK {
		t.Errorf("handler returned wrong status code for existing user: got %v want %v",
			status, http.StatusOK)
	}

	var fetchedUser service.User
	if err := json.NewDecoder(rr.Body).Decode(&fetchedUser); err != nil {
		t.Fatalf("Could not decode response for existing user: %v", err)
	}

	if fetchedUser.ID != createdUser.ID || fetchedUser.Name != createdUser.Name {
		t.Errorf("Fetched user mismatch. Expected %+v, got %+v", createdUser, fetchedUser)
	}

	// Test case 2: User not found
	req, err = http.NewRequest("GET", "/users/nonexistent", nil)
	if err != nil {
		t.Fatal(err)
	}

	rr = httptest.NewRecorder()
	handler.ServeHTTP(rr, req)

	if status := rr.Code; status != http.StatusNotFound {
		t.Errorf("handler returned wrong status code for non-existent user: got %v want %v",
			status, http.StatusNotFound)
	}
}
